class FbReader {
  final String en, km;
  final List<int> bg;
  final int bar, ink, muted;
  final bool dark;
  const FbReader(this.en, this.km, this.bg, this.bar, this.ink, this.muted, this.dark);
  String name(String lang) => lang == 'km' ? km : en;
}

